reply:
@prefix fis: <http://example.org/onto/securities#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology" ;
    rdfs:comment "Ontology modeling securities, financial instruments, bonds, stocks, derivatives, and funds as described in corpus passages drawn from general finance sources, IAS/IFRS standards, ECB glossary, and educational resources." .

#################################################################
# CLASSES
#################################################################

fis:FinancialInstrument a owl:Class ;
    rdfs:label "Financial Instrument" ;
    rdfs:comment "A monetary contract between parties; any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity (IAS 32/39)." .

fis:Security a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "Security" ;
    rdfs:comment "A tradable financial asset; a financial contract which entitles the holder to investment returns and represents a claim on the issuer that can be traded in financial markets." .

fis:CashInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "Cash Instrument" ;
    rdfs:comment "An instrument whose value is determined directly by the markets, e.g. securities, loans and deposits." .

fis:DerivativeInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "Derivative Instrument" ;
    rdfs:comment "An instrument which derives its value from the value and characteristics of one or more underlying entities such as an asset, index, or interest rate." .

owl:disjointWith fis:CashInstrument .

#### Top-level security classification ####

fis:DebtSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Debt Security" ;
    rdfs:comment "A negotiable financial instrument serving as evidence of a promise by the issuer to make one or more payments to the holder on specified future dates; the holder is entitled to payment of principal and interest." .

fis:EquitySecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Equity Security" ;
    rdfs:comment "A share of equity interest in an entity such as the capital stock of a company, trust or partnership; a negotiable instrument representing ownership of a stake in a corporation." .

fis:HybridSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Hybrid Security" ;
    rdfs:comment "A security that combines some of the characteristics of both debt and equity securities." .

fis:Derivative a owl:Class ;
    rdfs:subClassOf fis:Security, fis:DerivativeInstrument ;
    rdfs:label "Derivative" ;
    rdfs:comment "A contract between a buyer and seller whose value depends on the performance of an underlier; one of the three main categories of financial instruments (debt, equity, derivatives)." .

fis:InvestmentFund a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Investment Fund" ;
    rdfs:comment "A pooled investment vehicle (e.g. mutual fund, ETF) whose value is derived from a portfolio of underlying securities it holds." .

owl:AllDisjointClasses [
    owl:members ( fis:DebtSecurity fis:EquitySecurity fis:Derivative )
] .

#### Debt security subclasses ####

fis:Bond a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Bond" ;
    rdfs:comment "A type of security under which the issuer owes the holder a debt and is obliged to repay principal at maturity and usually pay interest (coupon) over time; a certificate of debt generally long-term." .

fis:MoneyMarketInstrument a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Money Market Instrument" ;
    rdfs:comment "A short-term debt instrument with original maturity of one year or less, highly liquid, sometimes referred to as near cash." .

owl:disjointWith fis:Bond .

fis:CommercialPaper a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Commercial Paper" ;
    rdfs:comment "An unsecured promissory note with a fixed maturity usually less than 270 days, issued at a discount to face value and redeemed at face value." .

fis:CertificateOfDeposit a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Certificate of Deposit" ;
    rdfs:comment "A time deposit sold by banks, thrift institutions, and credit unions with a specific fixed term before money can be withdrawn without penalty." .

fis:TreasuryBill a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Treasury Bill" ;
    rdfs:comment "Short-term debt obligation of a national government issued to mature in three to twelve months; a zero-coupon bond that matures in one year or less." .

fis:GovernmentBond a owl:Class ;
    rdfs:label "Government Bond" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ]
        )
    ] ;
    rdfs:comment "A form of bond issued by a sovereign government to support public spending; also called treasury bond or sovereign bond. Medium or long term debt securities issued by sovereign governments or their agencies." .

fis:SupranationalBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Supranational Bond" ;
    rdfs:comment "A bond issued by a supranational organization such as the World Bank, the IMF, or regional multilateral development banks." .

fis:MunicipalBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Municipal Bond" ;
    rdfs:comment "A bond issued by state or local governments, or entities they create such as authorities and special districts; known as a muni; sub-sovereign government bond." .

fis:CorporateBond a owl:Class ;
    rdfs:label "Corporate Bond" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ]
        )
    ] ;
    rdfs:comment "A bond issued by a corporation in order to raise financing; represents the debt of commercial or industrial entities." .

owl:AllDisjointClasses [
    owl:members ( fis:GovernmentBond fis:SupranationalBond fis:MunicipalBond fis:CorporateBond )
] .

fis:WarBond a owl:Class ;
    rdfs:subClassOf fis:GovernmentBond ;
    rdfs:label "War Bond" ;
    rdfs:comment "A bond issued by a government to fund military operations and other expenditure during wartime." .

fis:RevenueBond a owl:Class ;
    rdfs:subClassOf fis:MunicipalBond ;
    rdfs:label "Revenue Bond" ;
    rdfs:comment "A special type of municipal bond distinguished by its guarantee of repayment solely from revenues generated by a specified revenue-generating entity; typically non-recourse." .

fis:GeneralObligationBond a owl:Class ;
    rdfs:subClassOf fis:MunicipalBond ;
    rdfs:label "General Obligation Bond" ;
    rdfs:comment "Principal and interest secured by the full faith and credit of the issuer and usually supported by the issuer's taxing power." .

fis:AssessmentBond a owl:Class ;
    rdfs:subClassOf fis:GeneralObligationBond ;
    rdfs:label "Assessment Bond" ;
    rdfs:comment "Bonds that promise repayment based on property tax assessments of properties located within the issuer's boundaries." .

owl:AllDisjointClasses [
    owl:members ( fis:GeneralObligationBond fis:RevenueBond )
] .

fis:HighYieldBond a owl:Class ;
    rdfs:subClassOf fis:CorporateBond ;
    rdfs:label "High-Yield Bond" ;
    rdfs:comment "Also called junk bond; bonds rated below investment grade by credit rating agencies, carrying higher yield due to higher default risk." .

fis:InvestmentGradeBond a owl:Class ;
    rdfs:subClassOf fis:CorporateBond ;
    rdfs:label "Investment Grade Bond" ;
    rdfs:comment "Also called high grade bond; bonds rated AAA, AA, A, or BBB." .

owl:disjointWith fis:HighYieldBond .

fis:AssetBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Asset-Backed Security" ;
    rdfs:comment "Bonds whose interest and principal payments are backed by underlying cash flows from other assets; umbrella term for a security backed by a pool of assets, encompassing ABS, MBS and CDOs." .

fis:MortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "Mortgage-Backed Security" ;
    rdfs:comment "A type of asset-backed security secured by a mortgage or collection of mortgages." .

fis:CollateralizedDebtObligation a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "Collateralized Debt Obligation" ;
    rdfs:comment "A type of structured asset-backed security backed by debt obligations, often other asset-backed securities, sliced into tranches." .

fis:CoveredBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Covered Bond" ;
    rdfs:comment "Bonds backed by cash flows from mortgages or public sector assets; unlike asset-backed securities, the assets remain on the issuer's balance sheet." .

owl:disjointWith fis:AssetBackedSecurity .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Residential Mortgage-Backed Security" ;
    rdfs:comment "An RMBS is secured by single-family, one- to four-unit residential real estate." .

fis:CommercialMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Commercial Mortgage-Backed Security" ;
    rdfs:comment "A CMBS is secured by commercial and multi-family properties." .

owl:disjointWith fis:ResidentialMortgageBackedSecurity .

fis:CollateralizedMortgageObligation a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Collateralized Mortgage Obligation" ;
    rdfs:comment "Also called a pay-through bond; a debt obligation collateralized by the assets it owns, divided into classes with different maturities and payment priorities." .

fis:StrippedMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Stripped Mortgage-Backed Security" ;
    rdfs:comment "SMBS where mortgage payments' principal and interest components are separated into interest-only and principal-only securities." .

fis:SubordinatedBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Subordinated Bond" ;
    rdfs:comment "A bond that has a lower priority than other bonds of the issuer in case of liquidation; debt that is not senior." .

fis:SeniorBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Senior Bond" ;
    rdfs:comment "A bond contractually senior to other unsecured debt, giving holders priority in bankruptcy of the issuer." .

owl:disjointWith fis:SubordinatedBond .

fis:ZeroCouponBond a owl:Class ;
    rdfs:label "Zero-Coupon Bond" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0"^^xsd:decimal ]
        )
    ] ;
    rdfs:comment "A bond in which the face value is repaid at maturity with no periodic interest payments; issued at a substantial discount to par value, also called discount bond or deep discount bond." .

fis:FixedRateBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Fixed Rate Bond" ;
    rdfs:comment "A bond with interest payments (coupon) that remain constant throughout the life of the bond." .

fis:FloatingRateNote a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Floating Rate Note" ;
    rdfs:comment "A bond with a variable coupon linked to a reference rate of interest such as LIBOR or SOFR, recalculated periodically." .

fis:InflationIndexedBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Inflation-Indexed Bond" ;
    rdfs:comment "A bond (linker) in which the principal amount and interest payments are indexed to the level of consumer prices." .

owl:AllDisjointClasses [
    owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond )
] .

fis:PerpetualBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Perpetual Bond" ;
    rdfs:comment "A bond with no maturity date, also called a perpetuity or 'Perp'." .

fis:SerialBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Serial Bond" ;
    rdfs:comment "A bond that matures in installments over a period of time." .

fis:CallableBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Callable Bond" ;
    rdfs:comment "A bond that gives the issuer the right to repay the bond before the maturity date on call dates." .

fis:PutableBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Putable Bond" ;
    rdfs:comment "A bond that gives the holder the right to force the issuer to repay the bond before the maturity date on put dates; also called a retractable bond." .

fis:BulletBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Bullet Bond" ;
    rdfs:comment "A straight bond that is neither callable nor putable." .

fis:ConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:Bond, fis:HybridSecurity ;
    rdfs:label "Convertible Bond" ;
    rdfs:comment "A type of bond that the holder can convert into a specified number of shares of common stock in the issuing company or cash of equal value; a hybrid security with debt and equity features." .

fis:ExchangeableBond a owl:Class ;
    rdfs:subClassOf fis:Bond, fis:HybridSecurity ;
    rdfs:label "Exchangeable Bond" ;
    rdfs:comment "Allows exchange into shares of a corporation other than the issuer." .

owl:disjointWith fis:ConvertibleBond .

fis:MandatoryConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:label "Mandatory Convertible Bond" ;
    rdfs:comment "A convertible bond that forces the holder to convert into shares at maturity." .

fis:ContingentConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:MandatoryConvertibleBond ;
    rdfs:label "Contingent Convertible Bond" ;
    rdfs:comment "A variation of mandatory convertibles automatically converted into equity if a pre-specified trigger event occurs, e.g. CoCo bonds." .

fis:PackagedConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:label "Packaged Convertible Bond" ;
    rdfs:comment "A straight bond and a call option/warrant wrapped together, tradeable separately as two legs." .

fis:SyntheticConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:label "Synthetic Convertible Bond" ;
    rdfs:comment "Synthetically structured convertible bond issued by an investment bank to replicate a convertible payoff on a specific underlying equity, settled in cash." .

fis:BearerBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Bearer Bond" ;
    rdfs:comment "An official certificate issued without a named holder; whoever possesses the paper certificate can claim the value of the bond." .

fis:RegisteredBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Registered Bond" ;
    rdfs:comment "A bond whose ownership is recorded by the issuer or a transfer agent." .

fis:BookEntryBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Book-Entry Bond" ;
    rdfs:comment "A bond that does not have a paper certificate." .

owl:AllDisjointClasses [
    owl:members ( fis:BearerBond fis:RegisteredBond fis:BookEntryBond )
] .

fis:TreasuryNote a owl:Class ;
    rdfs:subClassOf fis:GovernmentBond ;
    rdfs:label "Treasury Note" ;
    rdfs:comment "US Treasury security with maturity of two, three, five or ten years, with fixed coupon payments every six months." .

fis:TreasuryBond a owl:Class ;
    rdfs:subClassOf fis:GovernmentBond ;
    rdfs:label "Treasury Bond" ;
    rdfs:comment "US Treasury security with the longest maturity, from twenty to thirty years, with coupon payments every six months." .

fis:TreasuryInflationProtectedSecurity a owl:Class ;
    rdfs:subClassOf fis:GovernmentBond, fis:InflationIndexedBond ;
    rdfs:label "Treasury Inflation-Protected Security" ;
    rdfs:comment "TIPS: an inflation-indexed bond whose principal is adjusted to the Consumer Price Index." .

#### Equity security subclasses ####

fis:Stock a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "Stock" ;
    rdfs:comment "Consists of all the shares by which ownership of a corporation or company is divided; a share of stock means fractional ownership of the corporation." .

fis:CommonStock a owl:Class ;
    rdfs:subClassOf fis:Stock ;
    rdfs:label "Common Stock" ;
    rdfs:comment "A form of corporate equity ownership, typically carrying voting rights and lowest priority in dividends and liquidation; also called ordinary share or voting share." .

fis:PreferredStock a owl:Class ;
    rdfs:subClassOf fis:Stock, fis:HybridSecurity ;
    rdfs:label "Preferred Stock" ;
    rdfs:comment "Also called preferred shares or preference shares; a component of share capital with features of both equity and debt instruments, senior to common stock but subordinate to bonds." .

owl:disjointWith fis:CommonStock .

fis:ConvertiblePreferredStock a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "Convertible Preferred Stock" ;
    rdfs:comment "Preferred stock that includes the ability of the holder to convert the preferred shares into a fixed number of common shares." .

fis:CumulativePreferredStock a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "Cumulative Preferred Stock" ;
    rdfs:comment "A preferred stock that requires the company to make up any missed dividend payments before common stock dividends can be paid again." .

fis:NoncumulativePreferredStock a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "Noncumulative Preferred Stock" ;
    rdfs:comment "Also called straight preferred stock; passed dividends are lost if not declared." .

owl:disjointWith fis:CumulativePreferredStock .

fis:RestrictedStock a owl:Class ;
    rdfs:subClassOf fis:Stock ;
    rdfs:label "Restricted Stock" ;
    rdfs:comment "Rule 144 Stock: shares of stock subject to SEC Rule 144, acquired in unregistered form through private sales." .

fis:DepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "Depositary Receipt" ;
    rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities, trading on a local stock exchange." .

fis:AmericanDepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "American Depositary Receipt" ;
    rdfs:comment "A depositary receipt listed and traded in the United States." .

fis:EuropeanDepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "European Depositary Receipt" ;
    rdfs:comment "A depositary receipt issued by European banks." .

fis:GlobalDepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "Global Depositary Receipt" ;
    rdfs:comment "A depositary receipt issued by other banks (not US or European specifically)." .

owl:AllDisjointClasses [
    owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt )
] .

fis:EquityWarrant a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity ;
    rdfs:label "Equity Warrant" ;
    rdfs:comment "Options issued by the company that allow the holder to purchase a specific number of shares at a specified price within a specified time." .

fis:Convertible a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity ;
    rdfs:label "Convertible" ;
    rdfs:comment "Bonds or preferred stocks that can be converted, at the election of the holder, into the ordinary shares of the issuing company." .

#### Derivative subclasses ####

fis:Forward a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Forward" ;
    rdfs:comment "A non-standardized contract between two parties to buy or sell an asset at a specified future time at an amount agreed upon today." .

fis:Future a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Future" ;
    rdfs:comment "A standardized legal contract to buy or sell something at a predetermined price for delivery at a specified future time, traded on an exchange." .

fis:Option a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Option" ;
    rdfs:comment "A contract which gives the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." .

fis:Swap a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Swap" ;
    rdfs:comment "A derivative in which two counterparties exchange cash flows of one party's financial instrument for those of the other party's financial instrument." .

owl:AllDisjointClasses [
    owl:members ( fis:Forward fis:Future fis:Option fis:Swap )
] .

fis:LockProduct a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Lock Product" ;
    rdfs:comment "Derivatives (such as swaps, futures, or forwards) that obligate the contractual parties to the terms over the life of the contract." .

fis:OptionProduct a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Option Product" ;
    rdfs:comment "Derivatives that provide the buyer the right, but not the obligation, to enter the contract under the terms specified." .

owl:disjointWith fis:LockProduct .

fis:CallOption a owl:Class ;
    rdfs:label "Call Option" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Option
            [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "call" ]
        )
    ] ;
    rdfs:comment "An option that conveys to the owner the right to buy something at a certain price." .

fis:PutOption a owl:Class ;
    rdfs:label "Put Option" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Option
            [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "put" ]
        )
    ] ;
    rdfs:comment "An option that conveys the right of the owner to sell something at a certain price." .

owl:disjointWith fis:CallOption .

fis:AmericanOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "American Option" ;
    rdfs:comment "An option that may be exercised on any trading day on or before expiration." .

fis:EuropeanOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "European Option" ;
    rdfs:comment "An option that may only be exercised on expiry." .

fis:BermudanOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Bermudan Option" ;
    rdfs:comment "An option that may be exercised only on specified dates on or before expiration." .

fis:AsianOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Asian Option" ;
    rdfs:comment "An option whose payoff is determined by the average underlying price over some preset time period." .

fis:BarrierOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Barrier Option" ;
    rdfs:comment "An option with the characteristic that the underlying security's price must pass a certain level or barrier before it can be exercised." .

fis:BinaryOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Binary Option" ;
    rdfs:comment "An all-or-nothing option that pays the full amount if the underlying security meets the defined condition on expiration." .

fis:ExoticOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Exotic Option" ;
    rdfs:comment "A broad category of options that may include complex financial structures." .

owl:AllDisjointClasses [
    owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption )
] .

fis:StockOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Stock Option" ;
    rdfs:comment "A class of option whose underlying asset is the price of an equity." .

fis:EmployeeStockOption a owl:Class ;
    rdfs:subClassOf fis:StockOption ;
    rdfs:label "Employee Stock Option" ;
    rdfs:comment "An option a company awards to its employees as a form of incentive compensation." .

fis:Warrant a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Warrant" ;
    rdfs:comment "A long-dated option, generally traded over the counter, apart from commonly used short-dated options." .

fis:CreditDefaultSwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Credit Default Swap" ;
    rdfs:comment "A financial swap agreement in which the seller compensates the buyer in the event of a loan default or other credit event." .

fis:InterestRateSwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Interest Rate Swap" ;
    rdfs:comment "A contractual agreement to exchange cash flows representing streams of periodic interest payments in one currency." .

fis:CurrencySwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Currency Swap" ;
    rdfs:comment "A contractual agreement to exchange cash flows representing streams of periodic interest payments in two different currencies; also called cross-currency swap." .

owl:AllDisjointClasses [
    owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap )
] .

fis:StockFuture a owl:Class ;
    rdfs:subClassOf fis:Future ;
    rdfs:label "Stock Future" ;
    rdfs:comment "A cash-settled futures contract on the value of a particular stock market index or an individual firm's stock." .

fis:ForwardRateAgreement a owl:Class ;
    rdfs:subClassOf fis:Forward ;
    rdfs:label "Forward Rate Agreement" ;
    rdfs:comment "A contract to pay a fixed rate of interest at a future date on a notional amount of money." .

fis:ExchangeTradedDerivative a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Exchange-Traded Derivative" ;
    rdfs:comment "Derivatives instruments traded via specialized derivatives exchanges or other exchanges." .

fis:OverTheCounterDerivative a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Over-the-Counter Derivative" ;
    rdfs:comment "Contracts that are traded (and privately negotiated) directly between two parties, without going through an exchange." .

owl:disjointWith fis:ExchangeTradedDerivative .

#### Fund subclasses ####

fis:MutualFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Mutual Fund" ;
    rdfs:comment "An SEC-registered open-end investment fund that pools money from many investors to purchase securities." .

fis:ExchangeTradedFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Exchange-Traded Fund" ;
    rdfs:comment "An exchange-traded investment product registered as an open-end investment company or unit investment trust; shares trade on exchanges at market prices." .

owl:disjointWith fis:MutualFund .

fis:MoneyMarketFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Money Market Fund" ;
    rdfs:comment "A collective investment undertaking that primarily invests in money market instruments with residual maturity up to one year." .

fis:BondFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Bond Fund" ;
    rdfs:comment "Also called income fund; invests primarily in bonds or other types of debt securities." .

fis:EquityFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Equity Fund" ;
    rdfs:comment "Also called stock fund; invests primarily in stocks or equities." .

fis:IndexFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Index Fund" ;
    rdfs:comment "A passively managed fund that tracks the performance of an index, such as a stock market index or bond market index." .

fis:ActivelyManagedFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Actively Managed Fund" ;
    rdfs:comment "A fund that seeks to outperform stock market indices but generally charges higher fees." .

owl:disjointWith fis:IndexFund .

fis:HedgeFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Hedge Fund" ;
    rdfs:comment "A pooled investment vehicle that does not have many regulations to protect investors; available only to high-net-worth individuals; not typically referred to as a mutual fund." .

#### Issuer-related classes ####

fis:Issuer a owl:Class ;
    rdfs:label "Issuer" ;
    rdfs:comment "The entity which is obligated on a security or other financial instrument; the company or other entity issuing the security." .

fis:SovereignGovernment a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Sovereign Government" ;
    rdfs:comment "A national government that may issue government bonds." .

fis:Corporation a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Corporation" ;
    rdfs:comment "A commercial or industrial entity that may issue corporate bonds and stock." .

fis:SupranationalOrganization a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Supranational Organization" ;
    rdfs:comment "An international organization such as the World Bank or IMF that may issue supranational bonds." .

fis:LocalGovernment a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Local Government" ;
    rdfs:comment "A local or sub-sovereign governmental unit, such as a city or state, that may issue municipal bonds." .

#### Other relevant classes ####

fis:Shareholder a owl:Class ;
    rdfs:label "Shareholder" ;
    rdfs:comment "An individual or company that legally owns one or more shares of stock in a joint stock company; also called a stockholder." .

fis:Dividend a owl:Class ;
    rdfs:label "Dividend" ;
    rdfs:comment "A portion of a company's profit paid to shareholders; a discretionary distribution of ownership profits, in contrast to a coupon payment." .

fis:Coupon a owl:Class ;
    rdfs:label "Coupon" ;
    rdfs:comment "The interest payment that the issuer of a bond pays to the holder, usually at fixed intervals." .

fis:Underlying a owl:Class ;
    rdfs:label "Underlying" ;
    rdfs:comment "The asset (financial instrument, security, commodity, index, rate, or event) upon which a derivative's value depends." .

fis:CreditRating a owl:Class ;
    rdfs:label "Credit Rating" ;
    rdfs:comment "A grade assigned by a rating agency indicating the credit quality and default risk of an issuer or security." .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Issuer ;
    rdfs:label "has issuer" ;
    rdfs:comment "Relates a security to its issuer; a security has exactly one issuer." .

fis:isIssuerOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasIssuer ;
    rdfs:domain fis:Issuer ;
    rdfs:range fis:Security ;
    rdfs:label "is issuer of" .

fis:hasUnderlying a owl:ObjectProperty ;
    rdfs:domain fis:Derivative ;
    rdfs:range fis:Underlying ;
    rdfs:label "has underlying" ;
    rdfs:comment "Relates a derivative to the underlying asset, rate, index, or event from which its value is derived." .

fis:isUnderlyingOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasUnderlying ;
    rdfs:domain fis:Underlying ;
    rdfs:range fis:Derivative ;
    rdfs:label "is underlying of" .

fis:hasHolder a owl:ObjectProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Shareholder ;
    rdfs:label "has holder" ;
    rdfs:comment "Relates a security to a holder/investor." .

fis:isHolderOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasHolder ;
    rdfs:domain fis:Shareholder ;
    rdfs:range fis:Security ;
    rdfs:label "is holder of" .

fis:hasCreditRating a owl:ObjectProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range fis:CreditRating ;
    rdfs:label "has credit rating" ;
    rdfs:comment "Relates a debt security or issuer to its assigned credit rating." .

fis:isCreditRatingOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasCreditRating ;
    rdfs:domain fis:CreditRating ;
    rdfs:range fis:DebtSecurity ;
    rdfs:label "is credit rating of" .

fis:paysDividend a owl:ObjectProperty ;
    rdfs:domain fis:EquitySecurity ;
    rdfs:range fis:Dividend ;
    rdfs:label "pays dividend" ;
    rdfs:comment "Relates an equity security to the discretionary dividend distribution paid to holders." .

fis:isDividendOf a owl:ObjectProperty ;
    owl:inverseOf fis:paysDividend ;
    rdfs:domain fis:Dividend ;
    rdfs:range fis:EquitySecurity ;
    rdfs:label "is dividend of" .

fis:hasCouponPayment a owl:ObjectProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range fis:Coupon ;
    rdfs:label "has coupon payment" ;
    rdfs:comment "Relates a bond to its periodic coupon (interest) payment." .

fis:isCouponPaymentOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasCouponPayment ;
    rdfs:domain fis:Coupon ;
    rdfs:range fis:Bond ;
    rdfs:label "is coupon payment of" .

fis:hasConversionTarget a owl:ObjectProperty ;
    rdfs:domain fis:ConvertibleBond ;
    rdfs:range fis:CommonStock ;
    rdfs:label "has conversion target" ;
    rdfs:comment "Relates a convertible bond to the common stock it can be converted into." .

fis:holdsPortfolioAsset a owl:ObjectProperty ;
    rdfs:domain fis:InvestmentFund ;
    rdfs:range fis:Security ;
    rdfs:label "holds portfolio asset" ;
    rdfs:comment "Relates an investment fund to the securities in its underlying portfolio." .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:date ;
    rdfs:label "has maturity date" ;
    rdfs:comment "The date on which the principal of a debt security is due to be repaid; a bond has a single, defined maturity date (except perpetual bonds)." .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:decimal ;
    rdfs:label "has face value" ;
    rdfs:comment "Nominal, principal, par, or face amount on which the issuer pays interest and which must be repaid at maturity." .

fis:hasCouponRate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:decimal ;
    rdfs:label "has coupon rate" ;
    rdfs:comment "The interest rate that the issuer pays to the holder, expressed in annual terms." .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:decimal ;
    rdfs:label "has strike price" ;
    rdfs:comment "The price at which the sale takes place under an option contract; specified at the time the parties enter into the option." .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:date ;
    rdfs:label "has expiration date" ;
    rdfs:comment "The last date the option can be exercised." .

fis:hasOptionType a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:string ;
    rdfs:label "has option type" ;
    rdfs:comment "Indicates whether the option is a call or a put." .

fis:hasDeliveryDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Future ;
    rdfs:range xsd:date ;
    rdfs:label "has delivery date" ;
    rdfs:comment "The specified future date when delivery and payment occur under a futures contract." .

fis:hasNotionalAmount a owl:DatatypeProperty ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:decimal ;
    rdfs:label "has notional amount" ;
    rdfs:comment "The nominal or face amount used to calculate payments on swaps and other derivatives; this amount generally does not change hands." .

fis:hasParValue a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Stock ;
    rdfs:range xsd:decimal ;
    rdfs:label "has par value" ;
    rdfs:comment "A nominal accounting value used to represent the equity on the balance sheet of the corporation, declared per share of stock." .

fis:hasDividendYield a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:EquitySecurity ;
    rdfs:range xsd:decimal ;
    rdfs:label "has dividend yield" .

fis:hasYieldToMaturity a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:decimal ;
    rdfs:label "has yield to maturity" ;
    rdfs:comment "An estimate of the total rate of return anticipated to be earned by an investor who buys a bond at a given market price, holds it to maturity, and receives all interest payments and the capital redemption on schedule." .

fis:hasIssueDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:date ;
    rdfs:label "has issue date" .

fis:isVotingRight a owl:DatatypeProperty ;
    rdfs:domain fis:Stock ;
    rdfs:range xsd:boolean ;
    rdfs:label "is voting right" ;
    rdfs:comment "Indicates whether the stock carries voting rights, a distinguishing feature between common and preferred stock." .

fis:isCumulative a owl:DatatypeProperty ;
    rdfs:domain fis:PreferredStock ;
    rdfs:range xsd:boolean ;
    rdfs:label "is cumulative" ;
    rdfs:comment "Indicates whether unpaid preferred dividends accumulate (cumulative) or are lost (non-cumulative)." .

fis:isCallable a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:boolean ;
    rdfs:label "is callable" ;
    rdfs:comment "Indicates whether the issuer has the right to repay the bond before the maturity date." .

fis:isPutable a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:boolean ;
    rdfs:label "is putable" ;
    rdfs:comment "Indicates whether the holder has the right to force early repayment." .

#################################################################
# ADDITIONAL AXIOMS / COMMENTS
#################################################################

fis:Bond rdfs:comment "Note: the corpus presents conflicting enumerations of derivative subtypes - the common market taxonomy (forwards, futures, options, swaps as four siblings) versus the BIS taxonomy (forwards, swaps, options as three basic types, treating futures as a standardized forward). This ontology models the four-way split as the majority view, noting the BIS alternative in comments on fis:Future." .

fis:Future rdfs:comment "A futures contract differs from a forward contract in that the futures contract is standardized and exchange-traded via a clearing house; the forward contract is non-standardized and privately negotiated. NOTE: the Bank for International Settlements classifies derivatives into only three basic types (forwards, swaps, options), treating futures as a standardized exchange-traded variety of forward rather than a separate sibling category - this conflicts with the more common four-way taxonomy (forward, future, option, swap) used elsewhere in the corpus, which is adopted as the primary model here." .

fis:PreferredStock rdfs:comment "Preferred stock is classified under IAS 32 based on contractual substance rather than label: mandatorily redeemable preference shares are classified as financial liabilities (debt) rather than equity, while non-redeemable preference shares are equity. This accounting classification can diverge from the common market view of preferred stock as a hybrid equity instrument, modeled here as a HybridSecurity subclass of Stock per the majority/market-description sources." .

```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology" ;
    rdfs:comment "An ontology of securities, financial instruments, derivatives and investment funds, modelled from a corpus of descriptive texts (encyclopedic, educational, regulatory-glossary and standard-setting sources)." .

#################################################################
# TOP LEVEL: FinancialInstrument, CashInstrument, DerivativeInstrument
#################################################################

fis:FinancialInstrument a owl:Class ;
    rdfs:label "financial instrument" ;
    rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled. IAS 32/39 define it as any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity. The corpus states financial instruments can be either cash instruments or derivative instruments." .

fis:CashInstrument a owl:Class ;
    rdfs:label "cash instrument" ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:comment "Instruments whose value is determined directly by the markets, e.g. securities (readily transferable) and loans/deposits (requiring mutual agreement to transfer)." .

fis:DerivativeInstrument a owl:Class ;
    rdfs:label "derivative" ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:comment "A contract whose value is derived from the performance of an underlier such as a commodity, financial instrument, price index, currency or interest rate." .

fis:FinancialInstrument owl:equivalentClass [
    a owl:Class ;
    owl:unionOf ( fis:CashInstrument fis:DerivativeInstrument )
] .

owl:AllDisjointClasses [ owl:members ( fis:CashInstrument fis:DerivativeInstrument ) ] .

#################################################################
# Security and its three classic categories (US law)
#################################################################

fis:Security a owl:Class ;
    rdfs:label "security" ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:comment "A tradable financial asset. The legal definition varies by jurisdiction: in the US a security is 'a tradable financial asset of any kind' comprising debt, equity and derivatives; the UK FCA Handbook restricts the term to an enumerated list (equities, debentures, government/public securities, warrants, units, etc.); a narrower definition describes a security as 'a financial contract which entitles the holder to investment returns', secured by a legally enforceable contract. These definitions conflict on scope (e.g. whether derivatives count as securities); this ontology follows the broad US-style taxonomy (debt/equity/derivative) as the majority view, noting the conflict here." .

fis:DebtSecurity a owl:Class ;
    rdfs:label "debt security" , "fixed income security" ;
    rdfs:subClassOf fis:Security ;
    rdfs:comment "A security under which the holder is entitled to payment of principal and interest and other contractual rights. Called debentures, bonds, deposits, notes or commercial paper depending on maturity, collateral and other characteristics." .

fis:EquitySecurity a owl:Class ;
    rdfs:label "equity security" , "equity" ;
    rdfs:subClassOf fis:Security ;
    rdfs:comment "A share of equity interest in an entity such as the capital stock of a company, trust or partnership. Entitles the holder (shareholder) to a pro rata share of control and profit, and only a residual claim on liquidation, after creditors are paid." .

fis:HybridSecurity a owl:Class ;
    rdfs:label "hybrid security" ;
    rdfs:subClassOf fis:Security ;
    rdfs:comment "Securities that combine characteristics of both debt and equity securities, e.g. preference shares, convertibles and equity warrants. Deliberately overlaps with DebtSecurity/EquitySecurity, so is not disjoint from them." .

owl:AllDisjointClasses [ owl:members ( fis:DebtSecurity fis:EquitySecurity fis:DerivativeInstrument ) ] .

fis:Loan a owl:Class ; rdfs:label "loan" ; rdfs:subClassOf fis:CashInstrument ;
    rdfs:comment "A cash instrument such as a loan or deposit, where both borrower and lender must agree on a transfer (non-negotiable, unlike a security)." .

fis:Deposit a owl:Class ; rdfs:label "deposit" ; rdfs:subClassOf fis:CashInstrument .

owl:AllDisjointClasses [ owl:members ( fis:Security fis:Loan fis:Deposit ) ] .

#################################################################
# Issuer and Investor
#################################################################

fis:Issuer a owl:Class ; rdfs:label "issuer" ;
    rdfs:comment "The company or other entity issuing the security." .

fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "sovereign government" .
fis:Municipality a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "municipality" ,
    "local authority" ; rdfs:comment "A state, provincial, territorial, municipal or other governmental unit other than a sovereign government." .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer ;
    rdfs:comment "An international organization such as the World Bank, IMF or a regional development bank." .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .

owl:AllDisjointClasses [ owl:members ( fis:SovereignGovernment fis:Municipality fis:SupranationalOrganization fis:Corporation ) ] .

fis:Investor a owl:Class ; rdfs:label "investor" , "holder" .
fis:RetailInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
    rdfs:comment "Members of the public investing personally, other than by way of business." .
fis:InstitutionalInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
    rdfs:comment "Financial institutions acting on their own account or on behalf of clients, e.g. investment banks, insurance companies, pension funds." .

owl:AllDisjointClasses [ owl:members ( fis:RetailInvestor fis:InstitutionalInvestor ) ] .

fis:ClearingHouse a owl:Class ; rdfs:label "clearing house" ;
    rdfs:comment "An intermediary between the buyer and seller of a futures contract that mitigates the risk of default by either party." .

#################################################################
# Underlier hierarchy
#################################################################

fis:Underlier a owl:Class ; rdfs:label "underlier" , "underlying asset" ;
    rdfs:comment "The item that a derivative's value is derived from: can be a commodity, a financial instrument, a price index, a currency, or an interest rate." .

fis:FinancialInstrument rdfs:subClassOf fis:Underlier .
fis:Commodity a owl:Class ; rdfs:subClassOf fis:Underlier .
fis:Index a owl:Class ; rdfs:subClassOf fis:Underlier .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Underlier .
fis:InterestRate a owl:Class ; rdfs:subClassOf fis:Underlier .

#################################################################
# Object properties
#################################################################

fis:hasIssuer a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:FinancialInstrument ; rdfs:range fis:Issuer ;
    rdfs:comment "The entity issuing the security/instrument." .
fis:isIssuerOf a owl:ObjectProperty ; owl:inverseOf fis:hasIssuer ;
    rdfs:domain fis:Issuer ; rdfs:range fis:FinancialInstrument .

fis:hasHolder a owl:ObjectProperty ;
    rdfs:domain fis:FinancialInstrument ; rdfs:range fis:Investor .
fis:isHolderOf a owl:ObjectProperty ; owl:inverseOf fis:hasHolder ;
    rdfs:domain fis:Investor ; rdfs:range fis:FinancialInstrument .

fis:hasUnderlying a owl:ObjectProperty ;
    rdfs:domain fis:DerivativeInstrument ; rdfs:range fis:Underlier ;
    rdfs:comment "The item that can or must be bought or sold under the derivative contract." .
fis:isUnderlyingOf a owl:ObjectProperty ; owl:inverseOf fis:hasUnderlying ;
    rdfs:domain fis:Underlier ; rdfs:range fis:DerivativeInstrument .

fis:hasUnderlyingAsset a owl:ObjectProperty ;
    rdfs:domain fis:AssetBackedSecurity ; rdfs:range fis:Loan ;
    rdfs:comment "The pool of loans/receivables whose cash flows back an asset-backed security." .
fis:isUnderlyingAssetOf a owl:ObjectProperty ; owl:inverseOf fis:hasUnderlyingAsset ;
    rdfs:domain fis:Loan ; rdfs:range fis:AssetBackedSecurity .

fis:hasConversionTarget a owl:ObjectProperty ;
    rdfs:domain fis:Security ; rdfs:range fis:EquitySecurity ;
    rdfs:comment "The equity security that a convertible or warrant may be converted/exercised into." .
fis:isConversionTargetOf a owl:ObjectProperty ; owl:inverseOf fis:hasConversionTarget .

fis:hasReferenceEntity a owl:ObjectProperty ;
    rdfs:domain fis:CreditDefaultSwap ; rdfs:range fis:Issuer ;
    rdfs:comment "The entity whose debt obligation is referenced by a credit default swap." .
fis:isReferenceEntityOf a owl:ObjectProperty ; owl:inverseOf fis:hasReferenceEntity .

fis:hasHolding a owl:ObjectProperty ;
    rdfs:domain fis:InvestmentFund ; rdfs:range fis:Security ;
    rdfs:comment "A security held in the fund's portfolio." .
fis:isHoldingOf a owl:ObjectProperty ; owl:inverseOf fis:hasHolding .

fis:hasTrackedIndex a owl:ObjectProperty ;
    rdfs:domain fis:IndexFund ; rdfs:range fis:Index .
fis:isTrackedIndexOf a owl:ObjectProperty ; owl:inverseOf fis:hasTrackedIndex .

fis:hasClearingHouse a owl:ObjectProperty ;
    rdfs:domain fis:Future ; rdfs:range fis:ClearingHouse .
fis:isClearingHouseOf a owl:ObjectProperty ; owl:inverseOf fis:hasClearingHouse .

fis:hasDividend a owl:ObjectProperty ;
    rdfs:domain fis:Stock ; rdfs:range fis:Dividend .
fis:isDividendOf a owl:ObjectProperty ; owl:inverseOf fis:hasDividend .

fis:hasMeasurementCategory a owl:ObjectProperty ;
    rdfs:domain fis:FinancialAsset ; rdfs:range fis:MeasurementCategory ;
    rdfs:comment "IFRS 9 measurement classification of a financial asset." .
fis:isMeasurementCategoryOf a owl:ObjectProperty ; owl:inverseOf fis:hasMeasurementCategory .

#################################################################
# Datatype properties
#################################################################

fis:hasFaceValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "par value" , "nominal value" , "principal amount" ;
    rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal ;
    rdfs:comment "The amount on which the issuer pays interest and which is typically repaid at maturity." .

fis:hasMaturityDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "redemption date" ;
    rdfs:domain fis:DebtSecurity ; rdfs:range xsd:date .

fis:hasCouponRate a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:decimal .

fis:hasCouponType a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:string ;
    rdfs:comment "One of: fixed, floating, zero, inflation-indexed." .

fis:hasCreditRating a owl:DatatypeProperty ;
    rdfs:domain fis:DebtSecurity ; rdfs:range xsd:string .

fis:hasCreditGrade a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:string ;
    rdfs:comment "One of: investment-grade, high-yield." .

fis:hasYieldToMaturity a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:decimal .

fis:hasCallFeature a owl:DatatypeProperty ;
    rdfs:domain fis:Security ; rdfs:range xsd:boolean .

fis:hasPutFeature a owl:DatatypeProperty ;
    rdfs:domain fis:Security ; rdfs:range xsd:boolean .

fis:isPerpetual a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:boolean .

fis:hasRegistrationType a owl:DatatypeProperty ;
    rdfs:domain fis:Security ; rdfs:range xsd:string ;
    rdfs:comment "One of: bearer, registered, book-entry." .

fis:hasCollateral a owl:DatatypeProperty ;
    rdfs:domain fis:DebtSecurity ; rdfs:range xsd:boolean ;
    rdfs:comment "Whether the debt security is protected by collateral." .

fis:hasSeniority a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:string ;
    rdfs:comment "One of: senior, subordinated." .

fis:hasPurpose a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:string .

fis:hasVotingRight a owl:DatatypeProperty ;
    rdfs:domain fis:Stock ; rdfs:range xsd:boolean .

fis:isCumulative a owl:DatatypeProperty ;
    rdfs:domain fis:PreferredStock ; rdfs:range xsd:boolean .

fis:hasDividendType a owl:DatatypeProperty ;
    rdfs:domain fis:Dividend ; rdfs:range xsd:string ;
    rdfs:comment "One of: cash, stock." .

fis:hasStrikePrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:FinancialInstrument ; rdfs:range xsd:decimal .

fis:hasExpirationDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:FinancialInstrument ; rdfs:range xsd:date .

fis:hasExerciseStyle a owl:DatatypeProperty ;
    rdfs:domain fis:Option ; rdfs:range xsd:string ;
    rdfs:comment "One of: American, European, Bermudan." .

fis:hasOptionType a owl:DatatypeProperty ;
    rdfs:domain fis:Option ; rdfs:range xsd:string ;
    rdfs:comment "One of: Call, Put." .

fis:hasObligationNature a owl:DatatypeProperty ;
    rdfs:domain fis:DerivativeInstrument ; rdfs:range xsd:string ;
    rdfs:comment "One of: obligatory (lock products), optional (option products)." .

fis:isStandardized a owl:DatatypeProperty ;
    rdfs:domain fis:DerivativeInstrument ; rdfs:range xsd:boolean .

fis:hasNotionalAmount a owl:DatatypeProperty ;
    rdfs:domain fis:Swap ; rdfs:range xsd:decimal .

fis:hasPremium a owl:DatatypeProperty ;
    rdfs:domain fis:DerivativeInstrument ; rdfs:range xsd:decimal .

fis:hasConversionRatio a owl:DatatypeProperty ;
    rdfs:domain fis:ConvertibleBond ; rdfs:range xsd:decimal .

fis:hasConversionPrice a owl:DatatypeProperty ;
    rdfs:domain fis:ConvertibleBond ; rdfs:range xsd:decimal .

fis:hasCashFlowSource a owl:DatatypeProperty ;
    rdfs:domain fis:StrippedMortgageBackedSecurity ; rdfs:range xsd:string ;
    rdfs:comment "One of: interest, principal." .

fis:hasListingJurisdiction a owl:DatatypeProperty ;
    rdfs:domain fis:DepositaryReceipt ; rdfs:range xsd:string .

fis:isExchangeTraded a owl:DatatypeProperty ;
    rdfs:domain fis:InvestmentFund ; rdfs:range xsd:boolean .

fis:isRegulated a owl:DatatypeProperty ;
    rdfs:domain fis:InvestmentFund ; rdfs:range xsd:boolean .

fis:hasInvestmentStrategy a owl:DatatypeProperty ;
    rdfs:domain fis:InvestmentFund ; rdfs:range xsd:string ;
    rdfs:comment "One of: passive, active." .

fis:hasPrincipalAssetClass a owl:DatatypeProperty ;
    rdfs:domain fis:MutualFund ; rdfs:range xsd:string .

fis:hasNetAssetValue a owl:DatatypeProperty ;
    rdfs:domain fis:InvestmentFund ; rdfs:range xsd:decimal .

fis:hasDeliveryPrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:LockProduct ; rdfs:range xsd:decimal .

fis:hasDeliveryDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:LockProduct ; rdfs:range xsd:date .

#################################################################
# Bond hierarchy
#################################################################

fis:Bond a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:comment "A security under which the issuer owes the holder a debt and is obliged to repay principal at maturity plus interest (coupon) over time." .

fis:MoneyMarketInstrument a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:comment "Short-term debt instruments with original maturity of one year or less." .

fis:Bond owl:disjointWith fis:MoneyMarketInstrument .

# --- Issuer-based bond classification ---
fis:GovernmentBond a owl:Class ; rdfs:label "treasury bond" , "sovereign bond" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] .

fis:MunicipalBond a owl:Class ; rdfs:label "muni" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Municipality ] ) ] .

fis:SupranationalBond a owl:Class ; rdfs:label "supra" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] .

fis:CorporateBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

# --- Municipal bond subtypes ---
fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
    rdfs:comment "Principal and interest secured by the full faith and credit/taxing power of the issuer." .
fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
    rdfs:comment "Repayment from a specified stream of future income; typically non-recourse." .
fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond ;
    rdfs:comment "Repayment promised from property tax assessments within the issuer's boundaries." .
fis:BuildAmericaBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond .

# --- Corporate bond subtypes ---
fis:HighYieldBond a owl:Class ; rdfs:label "junk bond" , "non-investment grade bond" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCreditGrade ; owl:hasValue "high-yield" ] ) ] .
fis:InvestmentGradeBond a owl:Class ; rdfs:label "high grade bond" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCreditGrade ; owl:hasValue "investment-grade" ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:HighYieldBond fis:InvestmentGradeBond ) ] .

fis:BulletBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ;
    rdfs:comment "A straight bond that is neither callable nor putable." .

# --- Coupon-structure classification ---
fis:FixedRateBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "fixed" ] ) ] .
fis:FloatingRateNote a owl:Class ; rdfs:label "floater" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "floating" ] ) ] .
fis:ZeroCouponBond a owl:Class ; rdfs:label "deep discount bond" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "zero" ] ) ] ;
    rdfs:comment "Pays no periodic interest; sold at a deep discount to face value, which is repaid in full at maturity." .
fis:InflationIndexedBond a owl:Class ; rdfs:label "linker" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "inflation-indexed" ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond fis:InflationIndexedBond ) ] .

# --- Optionality ---
fis:CallableBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCallFeature ; owl:hasValue true ] ) ] .
fis:PutableBond a owl:Class ; rdfs:label "retractable bond" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasPutFeature ; owl:hasValue true ] ) ] .

fis:PerpetualBond a owl:Class ; rdfs:label "perpetuity" , "consol" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:isPerpetual ; owl:hasValue true ] ) ] .

# --- Form of ownership ---
fis:BearerSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasRegistrationType ; owl:hasValue "bearer" ] ) ] ;
    rdfs:comment "Entitles the holder to the rights under the security merely by holding it; transferred by delivery." .
fis:RegisteredSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasRegistrationType ; owl:hasValue "registered" ] ) ] ;
    rdfs:comment "Entitles the holder to rights only if registered on a security register." .
owl:AllDisjointClasses [ owl:members ( fis:BearerSecurity fis:RegisteredSecurity ) ] .

fis:BearerBond a owl:Class ; owl:equivalentClass [ owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] .
fis:RegisteredBond a owl:Class ; owl:equivalentClass [ owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] .
fis:BookEntryBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasRegistrationType ; owl:hasValue "book-entry" ] ) ] ;
    rdfs:comment "A bond with no paper certificate." .

# --- Security / seniority ---
fis:SecuredBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:DebtSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:hasValue true ] ) ] .
fis:UnsecuredBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:DebtSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:hasValue false ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:SecuredBond fis:UnsecuredBond ) ] .

fis:Debenture a owl:Class ; rdfs:subClassOf fis:UnsecuredBond ;
    rdfs:comment "An unsecured bond, typically with a long maturity of at least ten years." .

fis:SeniorBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:hasValue "senior" ] ) ] .
fis:SubordinatedBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:hasValue "subordinated" ] ) ] ;
    rdfs:comment "Lower priority than other bonds of the issuer in liquidation; usually a lower credit rating than senior bonds." .
owl:AllDisjointClasses [ owl:members ( fis:SeniorBond fis:SubordinatedBond ) ] .

fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "Backed by cash flows from mortgages or public-sector assets which, unlike asset-backed securities, remain on the issuer's balance sheet." .

# --- Purpose-based bonds ---
fis:WarBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasPurpose ; owl:hasValue "military" ] ) ] .
fis:ClimateBond a owl:Class ; rdfs:label "green bond" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasPurpose ; owl:hasValue "climate" ] ) ] .
fis:SocialImpactBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasPurpose ; owl:hasValue "social-outcome" ] ) ] .

#################################################################
# Asset-backed / mortgage-backed securities
#################################################################

fis:AssetBackedSecurity a owl:Class ; rdfs:label "ABS" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlyingAsset ; owl:someValuesFrom fis:Loan ] ) ] ;
    rdfs:comment "A bond whose interest and principal payments are backed by underlying cash flows from a pool of other assets (loans, leases, receivables)." .

fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Loan .
fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgage fis:CommercialMortgage ) ] .
fis:AutoLoan a owl:Class ; rdfs:subClassOf fis:Loan .
fis:StudentLoan a owl:Class ; rdfs:subClassOf fis:Loan .
fis:CreditCardReceivable a owl:Class ; rdfs:subClassOf fis:Loan .

fis:MortgageBackedSecurity a owl:Class ; rdfs:label "MBS" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlyingAsset ; owl:someValuesFrom fis:Mortgage ] ) ] .

fis:ResidentialMortgageBackedSecurity a owl:Class ; rdfs:label "RMBS" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:MortgageBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlyingAsset ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] .
fis:CommercialMortgageBackedSecurity a owl:Class ; rdfs:label "CMBS" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:MortgageBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlyingAsset ; owl:someValuesFrom fis:CommercialMortgage ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) ] .

fis:PassThroughSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:comment "Allocates cash flows from the underlying pool to holders pro rata." .
fis:CollateralizedMortgageObligation a owl:Class ; rdfs:label "CMO" , "pay-through bond" ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:comment "Divided into tranches with different maturities and priorities for receipt of principal/interest." .
fis:NetInterestMarginSecurity a owl:Class ; rdfs:label "NIMS" ; rdfs:subClassOf fis:MortgageBackedSecurity .

fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:label "SMBS" ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:comment "Each mortgage payment is split into interest and principal components, which can be separated into distinct securities." .
fis:InterestOnlyStrip a owl:Class ; rdfs:label "IO strip" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:StrippedMortgageBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCashFlowSource ; owl:hasValue "interest" ] ) ] .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:label "PO strip" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:StrippedMortgageBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCashFlowSource ; owl:hasValue "principal" ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) ] .

fis:CollateralizedDebtObligation a owl:Class ; rdfs:label "CDO" ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:comment "A structured ABS, originally for corporate debt markets, sliced into tranches by seniority; may be backed by other bonds/ABS." .

#################################################################
# Money market instruments
#################################################################

fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:comment "An unsecured promissory note with fixed maturity usually less than 270 days." .
fis:CertificateOfDeposit a owl:Class ; rdfs:label "CD" , "time deposit" ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:comment "A time deposit sold by banks, thrift institutions and credit unions, with a fixed term before withdrawal without penalty." .
fis:TreasuryBill a owl:Class ; rdfs:label "T-bill" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:MoneyMarketInstrument
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
    rdfs:comment "Short-term government debt obligation maturing in three to twelve months." .
fis:RepurchaseAgreement a owl:Class ; rdfs:label "repo" ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:comment "Short-term loan arranged by selling securities with an agreement to repurchase them at a fixed price on a fixed date." .
fis:BankersAcceptance a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .
fis:MunicipalNote a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .

#################################################################
# Equity / stock hierarchy
#################################################################

fis:Stock a owl:Class ; rdfs:label "share" , "capital stock" ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:comment "Consists of the shares by which ownership of a corporation is divided; in the UK/Ireland/South Africa/Australia 'stock' can also refer more broadly to any marketable security." .

fis:CommonStock a owl:Class ; rdfs:label "ordinary share" , "voting share" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Stock
        [ a owl:Restriction ; owl:onProperty fis:hasVotingRight ; owl:hasValue true ] ) ] ;
    rdfs:comment "Typically carries voting rights; owners of common stock do not directly own company assets and have lowest priority in dividends/liquidation." .

fis:PreferredStock a owl:Class ; rdfs:label "preference share" , "preferred share" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Stock
        [ a owl:Restriction ; owl:onProperty fis:hasVotingRight ; owl:hasValue false ] ) ] ;
    rdfs:subClassOf fis:HybridSecurity ;
    rdfs:comment "Senior to common stock in dividends and liquidation, subordinate to bonds; typically does not carry voting rights, though this varies by issue. The corpus treats preferred stock both as capital stock (equity) and as a hybrid instrument; both parent classes are retained to reflect this stated dual nature." .

owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

fis:CumulativePreferredStock a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:isCumulative ; owl:hasValue true ] ) ] ;
    rdfs:comment "Unpaid dividends accumulate as dividends in arrears and must be paid before common dividends resume." .
fis:NonCumulativePreferredStock a owl:Class ; rdfs:label "straight preferred stock" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:isCumulative ; owl:hasValue false ] ) ] ;
    rdfs:comment "Any passed dividend is lost rather than accumulated." .
owl:AllDisjointClasses [ owl:members ( fis:CumulativePreferredStock fis:NonCumulativePreferredStock ) ] .

fis:ConvertiblePreferredStock a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] ;
    rdfs:comment "Preferred stock convertible into a fixed number of common shares after a predetermined date." .

fis:CallablePreferredStock a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:hasCallFeature ; owl:hasValue true ] ) ] .

#################################################################
# Hybrid securities: convertibles, exchangeables, warrants
#################################################################

fis:ConvertibleBond a owl:Class ; rdfs:label "convertible note" , "convertible debenture" ;
    rdfs:subClassOf fis:Bond , fis:HybridSecurity ;
    rdfs:comment "A bond the holder can convert into a specified number of shares of the issuer's common stock or cash of equal value." .

fis:MandatoryConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:comment "Forces conversion into shares at maturity." .
fis:ContingentConvertibleBond a owl:Class ; rdfs:label "CoCo" ; rdfs:subClassOf fis:MandatoryConvertibleBond ;
    rdfs:comment "Automatically converts into equity if a pre-specified trigger event occurs." .

fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:Bond , fis:HybridSecurity ;
    rdfs:comment "Allows exchange for shares of a corporation other than the issuer." .

fis:ConvertibleNote a owl:Class ; rdfs:subClassOf fis:HybridSecurity ;
    rdfs:comment "A frequent vehicle for seed investing in startups; debt that converts to equity in a future investing round." .

fis:EquityWarrant a owl:Class ; rdfs:label "warrant" ;
    rdfs:subClassOf fis:HybridSecurity ;
    rdfs:comment "An option issued by a company allowing the holder to purchase a specific number of shares at a specified price within a specified time; often issued with bonds or existing equities. Note: the corpus elsewhere also lists warrants as a long-dated variant of an option (a derivative), illustrating a cross-cutting classification conflict between the hybrid-security view and the derivative/option view." .

#################################################################
# Depositary receipts
#################################################################

fis:DepositaryReceipt a owl:Class ; rdfs:label "DR" ;
    rdfs:subClassOf fis:Security ;
    rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities, traded on a local stock exchange." .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:label "ADR" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:DepositaryReceipt
        [ a owl:Restriction ; owl:onProperty fis:hasListingJurisdiction ; owl:hasValue "United States" ] ) ] .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:label "EDR" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:DepositaryReceipt
        [ a owl:Restriction ; owl:onProperty fis:hasListingJurisdiction ; owl:hasValue "Europe" ] ) ] .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:label "GDR" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:DepositaryReceipt
        [ a owl:Restriction ; owl:onProperty fis:hasListingJurisdiction ; owl:hasValue "Global" ] ) ] .

#################################################################
# Dividend
#################################################################

fis:Dividend a owl:Class ;
    rdfs:comment "A portion of a company's profit paid to shareholders; discretionary, unlike the contractually fixed coupon on debt." .
fis:CashDividend a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Dividend
        [ a owl:Restriction ; owl:onProperty fis:hasDividendType ; owl:hasValue "cash" ] ) ] .
fis:StockDividend a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Dividend
        [ a owl:Restriction ; owl:onProperty fis:hasDividendType ; owl:hasValue "stock" ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:CashDividend fis:StockDividend ) ] .

#################################################################
# Derivatives: lock products vs option products
#################################################################

fis:LockProduct a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:DerivativeInstrument
        [ a owl:Restriction ; owl:onProperty fis:hasObligationNature ; owl:hasValue "obligatory" ] ) ] ;
    rdfs:comment "Obligates the contractual parties to the terms over the life of the contract (swaps, futures, forwards)." .
fis:OptionProduct a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:DerivativeInstrument
        [ a owl:Restriction ; owl:onProperty fis:hasObligationNature ; owl:hasValue "optional" ] ) ] ;
    rdfs:comment "Provides the buyer the right, but not the obligation, to enter the contract under the terms specified." .
owl:AllDisjointClasses [ owl:members ( fis:LockProduct fis:OptionProduct ) ] .

fis:Forward a owl:Class ; rdfs:subClassOf fis:LockProduct ;
    owl:equivalentClass [ owl:intersectionOf ( fis:LockProduct
        [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue false ] ) ] ;
    rdfs:comment "A non-standardized, privately negotiated contract to buy or sell an asset at a specified future time for a price agreed today." .

fis:Future a owl:Class ; rdfs:label "futures contract" ; rdfs:subClassOf fis:LockProduct ;
    owl:equivalentClass [ owl:intersectionOf ( fis:LockProduct
        [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue true ] ) ] ;
    rdfs:comment "A standardized contract written by a clearing house/futures exchange to buy or sell an asset at a future date for a price agreed today." .
owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future ) ] .

fis:Swap a owl:Class ; rdfs:subClassOf fis:LockProduct ;
    rdfs:comment "A contract in which two counterparties exchange cash flows of one financial instrument for those of another, calculated over a notional principal amount." .
fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CommoditySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:EquitySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CreditDefaultSwap a owl:Class ; rdfs:label "CDS" ; rdfs:subClassOf fis:Swap ;
    rdfs:comment "The seller compensates the buyer in the event of a loan default or other credit event on a reference entity's obligation; the buyer pays a periodic fee (spread)." .

owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CommoditySwap fis:EquitySwap fis:CreditDefaultSwap ) ] .

fis:Option a owl:Class ; rdfs:subClassOf fis:OptionProduct ;
    rdfs:comment "Gives the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." .

fis:CallOption a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "Call" ] ) ] ;
    rdfs:comment "The right to buy the underlying at the strike price." .
fis:PutOption a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "Put" ] ) ] ;
    rdfs:comment "The right to sell the underlying at the strike price." .
owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

fis:AmericanOption a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "American" ] ) ] ;
    rdfs:comment "May be exercised on any trading day on or before expiration." .
fis:EuropeanOption a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "European" ] ) ] ;
    rdfs:comment "May only be exercised on expiry." .
fis:BermudanOption a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "Bermudan" ] ) ] ;
    rdfs:comment "May be exercised only on specified dates on or before expiration." .
owl:AllDisjointClasses [ owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) ] .

fis:AsianOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:comment "Payoff determined by the average underlying price over a preset period." .
fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:comment "The underlying security's price must pass a certain barrier before it can be exercised." .
fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:comment "An all-or-nothing option that pays the full amount if a condition is met at expiration." .
fis:ExoticOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:comment "Any option with complex financial structures beyond plain vanilla." .

fis:ExchangeTradedDerivative a owl:Class ; rdfs:label "ETD" ; rdfs:subClassOf fis:DerivativeInstrument ;
    rdfs:comment "Traded via specialized derivatives exchanges with standardized contracts." .
fis:OverTheCounterDerivative a owl:Class ; rdfs:label "OTC derivative" ; rdfs:subClassOf fis:DerivativeInstrument ;
    rdfs:comment "Privately negotiated directly between two parties, without an exchange or intermediary." .
owl:AllDisjointClasses [ owl:members ( fis:ExchangeTradedDerivative fis:OverTheCounterDerivative ) ] .

#################################################################
# Investment funds
#################################################################

fis:InvestmentFund a owl:Class ;
    rdfs:comment "An investment vehicle that pools money from many investors to purchase securities, forming a portfolio." .

fis:MutualFund a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue false ] ) ] ;
    rdfs:comment "An SEC-registered open-end investment company; shares are purchased from/sold to the issuer at NAV." .

fis:ExchangeTradedFund a owl:Class ; rdfs:label "ETF" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue true ] ) ] ;
    rdfs:comment "Shares trade on national securities exchanges at market prices that may be a premium or discount to NAV." .
owl:AllDisjointClasses [ owl:members ( fis:MutualFund fis:ExchangeTradedFund ) ] .

fis:HedgeFund a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:isRegulated ; owl:hasValue false ] ) ] ;
    rdfs:comment "Pools investor money like a mutual fund but is subject to far fewer regulations; uses more flexible/risky strategies such as leverage and short-selling." .

fis:IndexFund a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:hasInvestmentStrategy ; owl:hasValue "passive" ] ) ] ;
    rdfs:comment "Passively managed fund that tracks the performance of an index." .
fis:ActivelyManagedFund a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:hasInvestmentStrategy ; owl:hasValue "active" ] ) ] ;
    rdfs:comment "Seeks to outperform market indices; generally charges higher fees than index funds." .
owl:AllDisjointClasses [ owl:members ( fis:IndexFund fis:ActivelyManagedFund ) ] .

fis:MoneyMarketFund a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:MutualFund
        [ a owl:Restriction ; owl:onProperty fis:hasPrincipalAssetClass ; owl:hasValue "money market" ] ) ] .
fis:BondFund a owl:Class ; rdfs:label "income fund" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:MutualFund
        [ a owl:Restriction ; owl:onProperty fis:hasPrincipalAssetClass ; owl:hasValue "bond" ] ) ] .
fis:EquityFund a owl:Class ; rdfs:label "stock fund" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:MutualFund
        [ a owl:Restriction ; owl:onProperty fis:hasPrincipalAssetClass ; owl:hasValue "equity" ] ) ] .
fis:BalancedFund a owl:Class ; rdfs:label "hybrid fund" ;
    owl:equivalentClass [ owl:intersectionOf ( fis:MutualFund
        [ a owl:Restriction ; owl:onProperty fis:hasPrincipalAssetClass ; owl:hasValue "hybrid" ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:MoneyMarketFund fis:BondFund fis:EquityFund fis:BalancedFund ) ] .

fis:InverseExchangeTradedFund a owl:Class ; rdfs:label "IETF" ; rdfs:subClassOf fis:ExchangeTradedFund ;
    rdfs:comment "Designed to move opposite to its benchmark index." .
fis:LeveragedExchangeTradedFund a owl:Class ; rdfs:label "LETF" ; rdfs:subClassOf fis:ExchangeTradedFund ;
    rdfs:comment "Seeks to amplify the benchmark's daily return." .

#################################################################
# IAS 32 / IFRS 9 accounting classification (cross-cutting)
#################################################################

fis:FinancialAsset a owl:Class ;
    rdfs:comment "IAS 32: cash, an equity instrument of another entity, a contractual right to receive cash or another financial asset, or a contractual right to exchange financial instruments under potentially favourable conditions. NOTE: this accounting classification can diverge from the market taxonomy above, e.g. a mandatorily redeemable preference share is a FinancialLiability under IAS 32 even though it is commonly called 'preferred equity' in the market." .

fis:FinancialLiability a owl:Class ;
    rdfs:comment "IAS 32: a contractual obligation to deliver cash or another financial asset to another entity, or to exchange financial instruments under potentially unfavourable conditions." .

owl:AllDisjointClasses [ owl:members ( fis:FinancialAsset fis:FinancialLiability ) ] .

fis:EquityInstrument a owl:Class ;
    rdfs:comment "IAS 32: any contract that evidences a residual interest in the assets of an entity after deducting all of its liabilities. Classification here depends on the absence of a contractual obligation to deliver cash, not on the instrument's legal label." .

fis:MeasurementCategory a owl:Class ;
    rdfs:comment "IFRS 9 subsequent measurement classification for a financial asset." .
fis:AmortizedCostMeasurement a owl:Class ; rdfs:subClassOf fis:MeasurementCategory .
fis:FairValueThroughOtherComprehensiveIncomeMeasurement a owl:Class ; rdfs:label "FVOCI" ; rdfs:subClassOf fis:MeasurementCategory .
fis:FairValueThroughProfitOrLossMeasurement a owl:Class ; rdfs:label "FVTPL" ; rdfs:subClassOf fis:MeasurementCategory .
owl:AllDisjointClasses [ owl:members ( fis:AmortizedCostMeasurement fis:FairValueThroughOtherComprehensiveIncomeMeasurement fis:FairValueThroughProfitOrLossMeasurement ) ] .
